"use client";

import { AnimatePresence } from "motion/react";
import { useId, useRef, useState } from "react";

import { BlockFrame } from "../parts/block-frame";
import { useTimeouts } from "./shared/use-timeouts";
import { AppPage } from "./support-widget/app-page";
import { HelpPanel, type PanelView } from "./support-widget/help-panel";
import { Launcher } from "./support-widget/launcher";
import type { PanelLine } from "./support-widget/panel-chat";

const DEPTH = { home: 0, article: 1, chat: 1 } satisfies Record<PanelView["name"], number>;

const GREETING: PanelLine = { id: "g1", from: "agent", text: "Hi Lena, I saw the insurer export failed this morning. Want me to look at it with you?" };

/**
 * An app page with a help launcher in the corner. The launcher opens a panel
 * with live article search, an article reader and a chat with the team.
 * Escape closes the panel and puts focus back on the launcher.
 */
export function SupportWidget({ className }: { className?: string }) {
  const [open, setOpen] = useState(false);
  const [view, setView] = useState<PanelView>({ name: "home" });
  const [direction, setDirection] = useState(1);
  const [query, setQuery] = useState("");
  const [lines, setLines] = useState<PanelLine[]>([GREETING]);
  const [unread, setUnread] = useState(1);
  const [typing, setTyping] = useState(false);
  const launcher = useRef<HTMLButtonElement>(null);
  const openRef = useRef(open);
  const viewRef = useRef(view);
  openRef.current = open;
  viewRef.current = view;
  const later = useTimeouts();
  const panelId = useId();

  const goTo = (next: PanelView) => {
    setDirection(DEPTH[next.name] >= DEPTH[view.name] ? 1 : -1);
    setView(next);
    if (next.name === "chat") setUnread(0);
  };

  const close = () => {
    setOpen(false);
    launcher.current?.focus();
  };

  const toggle = () => {
    if (open) close();
    else {
      setOpen(true);
      if (view.name === "chat") setUnread(0);
    }
  };

  const send = (text: string) => {
    setLines((list) => [...list, { id: `l${Date.now()}`, from: "me", text }]);
    later(() => setTyping(true), 600);
    later(() => {
      setTyping(false);
      setLines((list) => [...list, { id: `l${Date.now()}`, from: "agent", text: "Thanks. The insurer connection expired on Friday. I have sent you a link to sign in again, then the export runs on its own." }]);
      // An answer that lands while the panel is shut, or on another view, waits as unread.
      if (!openRef.current || viewRef.current.name !== "chat") setUnread((count) => count + 1);
    }, 2200);
  };

  return (
    <BlockFrame aria-label="Fernhill exports with help" className={className}>
      <div className="relative min-h-144">
        <AppPage />
        <AnimatePresence>
          {open ? (
            <HelpPanel
              id={panelId}
              view={view}
              direction={direction}
              onView={goTo}
              onClose={close}
              query={query}
              onQuery={setQuery}
              lines={lines}
              onSend={send}
              typing={typing}
              unread={unread}
            />
          ) : null}
        </AnimatePresence>
        <Launcher ref={launcher} open={open} onToggle={toggle} unread={unread} panelId={panelId} />
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Schedules timers that are all cleared when the component unmounts, so a
 * simulated reply never lands on a block that is gone. Returns `later(run, ms)`.
 */
export function useTimeouts() {
  const ids = useRef(new Set<number>());
  useEffect(() => {
    const pending = ids.current;
    return () => {
      for (const id of pending) window.clearTimeout(id);
      pending.clear();
    };
  }, []);
  return useCallback((run: () => void, ms: number) => {
    const id = window.setTimeout(() => {
      ids.current.delete(id);
      run();
    }, ms);
    ids.current.add(id);
    return id;
  }, []);
}

import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";
import { EXPORTS, type ExportState } from "./data";

const NAV = ["Today", "Bookings", "Patients", "Exports", "Settings"];

const STATE = {
  ready: { label: "Ready", tone: cn(STATUS_SURFACE.good, STATUS_TEXT.good) },
  running: { label: "Running", tone: "bg-marketing-blue-surface text-marketing-blue-ink" },
  failed: { label: "Failed", tone: cn(STATUS_SURFACE.bad, STATUS_TEXT.bad) },
  paused: { label: "Paused", tone: "border border-border text-muted-foreground" },
} satisfies Record<ExportState, { label: string; tone: string }>;

/**
 * The sample app page the help launcher sits on: a short nav and a list of
 * scheduled exports with their states. It is scenery, so its links do nothing.
 */
export function AppPage() {
  return (
    <div className="flex flex-col">
      <nav aria-label="Fernhill" className="scroll-fade-effect-x scrollbar-none flex items-center gap-1 overflow-x-auto border-b border-border px-4 py-2">
        <span className="mr-3 text-sm font-semibold">Fernhill</span>
        {NAV.map((item) => (
          <a
            key={item}
            href="#exports"
            aria-current={item === "Exports" ? "page" : undefined}
            onClick={(event) => event.preventDefault()}
            className={cn(
              "rounded-md px-2.5 py-1.5 text-sm whitespace-nowrap outline-none focus-visible:ring-2 focus-visible:ring-ring",
              item === "Exports" ? "bg-muted font-medium text-foreground" : "text-muted-foreground hover:text-foreground",
            )}
          >
            {item}
          </a>
        ))}
      </nav>
      <div className="flex flex-col gap-1 px-5 pt-5 pb-24">
        <h2 id="exports" className="text-base font-semibold">
          Scheduled exports
        </h2>
        <p className="text-sm text-muted-foreground">Harbour Street sends these on their own. A failed run stays here until it runs again.</p>
        <ul className="mt-3 flex flex-col gap-1">
          {EXPORTS.map((item) => (
            <li key={item.id} className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 py-2">
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-sm font-medium">{item.name}</span>
                <span className="text-xs text-muted-foreground">
                  {item.schedule}. Last run {item.lastRun}
                </span>
              </span>
              <span className={cn("rounded-full px-2 py-0.5 text-xs font-medium", STATE[item.state].tone)}>{STATE[item.state].label}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

/** The three states a figure or a row can be in. */
