"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { KeyboardEvent } from "react";

import { Button } from "@/components/ui/button";

import { ChevronLeftIcon } from "../icons";
import { ArticleView } from "./article-view";
import { ARTICLES } from "./data";
import { PanelChat, type PanelLine } from "./panel-chat";
import { PanelHome } from "./panel-home";

/** The view the panel shows. */
export type PanelView = { name: "home" } | { name: "article"; id: string } | { name: "chat" };

/** Props for the help panel. */
export interface HelpPanelProps {
  id: string;
  view: PanelView;
  /** 1 when the last move went deeper, -1 when it came back, so views slide the way people travel. */
  direction: number;
  onView: (view: PanelView) => void;
  onClose: () => void;
  query: string;
  onQuery: (query: string) => void;
  lines: PanelLine[];
  onSend: (text: string) => void;
  typing: boolean;
  unread: number;
}

const SLIDE = {
  enter: (direction: number) => ({ x: `${direction * 2}rem`, opacity: 0 }),
  center: { x: 0, opacity: 1 },
  exit: (direction: number) => ({ x: `${direction * -2}rem`, opacity: 0 }),
};

/**
 * The panel the launcher opens: search and articles, one article, or the
 * chat. Views slide in the direction of travel, and Escape closes the panel.
 */
export function HelpPanel({ id, view, direction, onView, onClose, query, onQuery, lines, onSend, typing, unread }: HelpPanelProps) {
  const reduceMotion = useReducedMotion();
  const article = view.name === "article" ? ARTICLES.find((item) => item.id === view.id) : undefined;
  const title = view.name === "chat" ? "Chat with the team" : view.name === "article" ? "Help article" : "Help";

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    onClose();
  };

  return (
    <motion.div
      id={id}
      role="dialog"
      aria-label={title}
      onKeyDown={onKeyDown}
      initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.9, y: 16 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.92, y: 12 }}
      transition={reduceMotion ? { duration: 0.12 } : { type: "spring", stiffness: 420, damping: 32 }}
      className="absolute right-4 bottom-20 origin-bottom-right z-20 flex h-[min(30rem,calc(100%-6rem))] w-[min(22rem,calc(100%-2rem))] flex-col overflow-hidden rounded-2xl border border-border bg-popover text-popover-foreground shadow-xl backdrop-blur-md"
    >
      <div className="flex min-h-12 items-center gap-1 border-b border-border px-2">
        {view.name === "home" ? (
          <span className="px-2 text-sm font-semibold">Fernhill help</span>
        ) : (
          <Button type="button" variant="ghost" size="sm" onClick={() => onView({ name: "home" })}>
            <ChevronLeftIcon aria-hidden="true" />
            Back
          </Button>
        )}
      </div>
      <div className="relative min-h-0 flex-1 overflow-hidden">
        <AnimatePresence mode="popLayout" initial={false} custom={direction}>
          <motion.div
            key={view.name === "article" ? view.id : view.name}
            custom={direction}
            variants={reduceMotion ? undefined : SLIDE}
            initial={reduceMotion ? { opacity: 0 } : "enter"}
            animate={reduceMotion ? { opacity: 1 } : "center"}
            exit={reduceMotion ? { opacity: 0 } : "exit"}
            transition={{ duration: 0.22, ease: [0.2, 0, 0, 1] }}
            className="absolute inset-0 pt-3"
          >
            {view.name === "home" ? (
              <PanelHome query={query} onQuery={onQuery} onOpenArticle={(articleId) => onView({ name: "article", id: articleId })} onOpenChat={() => onView({ name: "chat" })} unread={unread} />
            ) : view.name === "article" && article ? (
              <ArticleView article={article} />
            ) : (
              <PanelChat lines={lines} onSend={onSend} typing={typing} />
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

