export function ArticleView({ article }: { article: Article }) {
  const [helped, setHelped] = useState<boolean | null>(null);
  const heading = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    heading.current?.focus();
  }, []);

  return (
    <div className="scroll-fade-effect-y scrollbar-none flex h-full flex-col overflow-y-auto px-4 pb-4">
      <h3 ref={heading} tabIndex={-1} className="rounded-sm pt-1 text-base font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring">
        {article.title}
      </h3>
      <div className="mt-2 flex flex-col gap-3 text-sm text-foreground">
        {article.body.map((paragraph) => (
          <p key={paragraph}>{paragraph}</p>
        ))}
      </div>
      <div className="mt-auto flex flex-wrap items-center gap-2 border-t border-border pt-3" role="group" aria-label="Did this help?">
        <p role="status" className="mr-auto text-sm text-muted-foreground">
          {helped === null ? "Did this help?" : helped ? "Thanks, glad it helped." : "Thanks. The team will improve it."}
