import { PEOPLE } from "../shared/people";

/** One line in the panel chat. */
export interface PanelLine {
  id: string;
  from: "agent" | "me";
  text: string;
}

/** Props for the chat view of the help panel. */
export interface PanelChatProps {
  lines: PanelLine[];
  onSend: (text: string) => void;
  /** Whether the agent is writing an answer. */
  typing: boolean;
}

/** The chat view: the conversation with the team and a field to write in. The field takes focus on open. */
export function PanelChat({ lines, onSend, typing }: PanelChatProps) {
  const [text, setText] = useState("");
  const field = useRef<HTMLInputElement>(null);
  const end = useRef<HTMLLIElement>(null);
  const fieldId = useId();

  useEffect(() => {
    field.current?.focus();
  }, []);

  useEffect(() => {
    end.current?.scrollIntoView({ block: "nearest" });
  }, [lines.length, typing]);

  const send = (event: FormEvent) => {
    event.preventDefault();
    if (!text.trim()) return;
    onSend(text.trim());
    setText("");
  };

  return (
    <div className="flex h-full flex-col">
      <ol role="log" aria-label="Chat with the team" className="scroll-fade-effect-y scrollbar-none flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto px-4 pb-3">
        {lines.map((line) => (
          <li key={line.id} className={cn("flex items-end gap-2", line.from === "me" && "flex-row-reverse")}>
            {line.from === "agent" ? <PersonAvatar person={PEOPLE.priya} size="sm" /> : null}
            <p
              className={cn(
                "max-w-[80%] rounded-2xl px-3 py-1.5 text-sm",
                line.from === "me" ? "rounded-br-md bg-primary text-primary-foreground" : "rounded-bl-md border border-border bg-background",
              )}
            >
              <span className="sr-only">{line.from === "me" ? "You: " : "Priya: "}</span>
              {line.text}
            </p>
          </li>
        ))}
        {typing ? <li className="pl-8 text-xs text-muted-foreground">Priya is writing</li> : null}
        <li ref={end} aria-hidden="true" />
      </ol>
      <form onSubmit={send} className="flex gap-2 border-t border-border p-3">
        <label htmlFor={fieldId} className="sr-only">
          Message the team
        </label>
        <Input ref={field} id={fieldId} value={text} onChange={(event) => setText(event.target.value)} placeholder="Write a message" autoComplete="off" />
        <Button type="submit" size="icon" aria-label="Send" disabled={!text.trim()}>
          <SendIcon aria-hidden="true" />
        </Button>
      </form>
    </div>
  );
}

