  orange: "bg-marketing-orange-surface text-marketing-orange-ink",
  amber: "bg-marketing-amber-surface text-marketing-amber-ink",
} satisfies Record<Hue, string>;

/** One person in the Fernhill sample world. */
export interface Person {
  name: string;
  /** The part of the name a sentence uses, such as "Amara". */
  short: string;
  hue: Hue;
}

/** Fernhill staff and the clinic people who appear across the support blocks. */
export const PEOPLE = {
  amara: { name: "Amara Osei", short: "Amara", hue: "blue" },
  tomas: { name: "Tomás Reyes", short: "Tomás", hue: "green" },
  lena: { name: "Lena Fischer", short: "Lena", hue: "purple" },
  kofi: { name: "Kofi Mensah", short: "Kofi", hue: "orange" },
  hana: { name: "Hana Sato", short: "Hana", hue: "pink" },
  priya: { name: "Priya Nair", short: "Priya", hue: "amber" },
  jonas: { name: "Jonas Berg", short: "Jonas", hue: "blue" },
  mia: { name: "Mia Clarke", short: "Mia", hue: "green" },
  omar: { name: "Omar Haddad", short: "Omar", hue: "purple" },
