"use client";

import { type KeyboardEvent, useEffect, useId, useRef } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ChevronRightIcon } from "../../parts/icons";
import { ChatIcon } from "../icons";
import { SearchField } from "../shared/search-field";
import { PersonAvatar } from "../shared/person-avatar";
import { PEOPLE } from "../shared/people";
import { ARTICLES, type Article } from "./data";

/** Props for the first view of the help panel. */
export interface PanelHomeProps {
  query: string;
  onQuery: (query: string) => void;
  onOpenArticle: (id: string) => void;
  onOpenChat: () => void;
  /** Agent messages the viewer has not read yet. */
  unread: number;
}

/** The articles whose title or summary holds every word of the query. */
export function matchArticles(query: string): Article[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return ARTICLES.filter((article) => words.every((word) => `${article.title} ${article.summary}`.toLowerCase().includes(word)));
}

/**
 * The panel's first view: a search field that filters the articles live, the
 * article list, and a way into the chat. Down from the field enters the list,
 * Up from the first article returns, and Enter in the field opens the top result.
 */
export function PanelHome({ query, onQuery, onOpenArticle, onOpenChat, unread }: PanelHomeProps) {
  const field = useRef<HTMLInputElement>(null);
  const list = useRef<HTMLUListElement>(null);
  const fieldId = useId();
  const listId = useId();
  const results = matchArticles(query);

  useEffect(() => {
    field.current?.focus();
  }, []);

  const items = () => Array.from(list.current?.querySelectorAll<HTMLButtonElement>("button") ?? []);

  const onFieldKey = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      items()[0]?.focus();
    } else if (event.key === "Enter") {
      event.preventDefault();
      const top = results[0];
      if (top) onOpenArticle(top.id);
    }
  };

  const onListKey = (event: KeyboardEvent<HTMLUListElement>) => {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    event.preventDefault();
    const buttons = items();
    const at = buttons.findIndex((button) => button === event.target);
    if (event.key === "ArrowUp" && at <= 0) field.current?.focus();
    else buttons[Math.min(buttons.length - 1, at + (event.key === "ArrowDown" ? 1 : -1))]?.focus();
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex flex-col gap-3 px-4 pt-4 pb-3">
        <p className="text-base font-semibold">Hi Lena, how can we help?</p>
        <div>
          <label htmlFor={fieldId} className="sr-only">
            Search help articles
          </label>
          <SearchField
            ref={field}
            id={fieldId}
            value={query}
            onChange={(event) => onQuery(event.target.value)}
            onKeyDown={onFieldKey}
            placeholder="Search, like export or pause"
            aria-controls={listId}
          />
        </div>
      </div>
      <p role="status" className="sr-only">
        {query ? `${results.length} ${results.length === 1 ? "article" : "articles"} found` : ""}
      </p>
      <ul ref={list} id={listId} aria-label="Help articles" onKeyDown={onListKey} className="scroll-fade-effect-y scrollbar-none flex min-h-0 flex-1 flex-col overflow-y-auto px-2">
        {results.map((article) => (
          <li key={article.id}>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => onOpenArticle(article.id)}
              className="w-full justify-start text-left"
            >
              <span className="flex w-full min-w-0 items-center gap-3 px-2 py-2 font-normal">
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="truncate text-sm font-medium">{article.title}</span>
                  <span className="truncate text-xs text-muted-foreground">{article.summary}</span>
                </span>
                <ChevronRightIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
              </span>
            </Button>
          </li>
        ))}
        {results.length === 0 ? <li className="px-2 py-6 text-center text-sm text-muted-foreground">No article matches. Ask the team below.</li> : null}
      </ul>
      <div className="border-t border-border p-2">
        <Button type="button" variant="ghost" size="sm" onClick={onOpenChat} className="w-full justify-start text-left">
          <span className="flex w-full min-w-0 items-center gap-3 p-2 font-normal">
          <span className="relative">
            <PersonAvatar person={PEOPLE.priya} />
            <ChatIcon aria-hidden="true" className="absolute -right-1 -bottom-1 size-4 rounded-full bg-card p-0.5" />
          </span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="text-sm font-medium">Chat with the team</span>
            <span className="truncate text-xs text-muted-foreground">Usually replies in 4 minutes</span>
          </span>
          {unread > 0 ? (
            <span className={cn("rounded-full px-1.5 text-xs font-semibold tabular-nums", "bg-marketing-orange-surface text-marketing-orange-ink")}>
              {unread}
              <span className="sr-only"> unread</span>
            </span>
          ) : null}
          </span>
        </Button>
      </div>
    </div>
  );
}

