"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Ref } from "react";

import { Button } from "@/components/ui/button";

import { XIcon } from "../../parts/icons";
import { ChatIcon } from "../icons";

/** Props for the round help launcher. */
export interface LauncherProps {
  open: boolean;
  onToggle: () => void;
  unread: number;
  panelId: string;
  ref?: Ref<HTMLButtonElement>;
}

const POP = { type: "spring", stiffness: 600, damping: 30 } as const;

/**
 * The round button in the corner that opens and closes the help panel. Its
 * icon and unread badge pop in on a snappy spring.
 */
export function Launcher({ open, onToggle, unread, panelId, ref }: LauncherProps) {
  const reduceMotion = useReducedMotion();
  const pop = reduceMotion ? { duration: 0 } : POP;
  return (
    <div className="absolute right-4 bottom-4 z-30">
      {/* The wrapper rounds the launcher and draws its focus ring, because Button keeps its own shape. */}
      <span className="flex overflow-hidden rounded-full shadow-lg has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-card">
      <Button
        ref={ref}
        type="button"
        size="icon"
        aria-expanded={open}
        aria-controls={panelId}
        aria-label={unread > 0 && !open ? `Help, ${unread} unread` : open ? "Close help" : "Help"}
        onClick={onToggle}
        className="size-12"
      >
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={open ? "close" : "chat"}
            initial={{ scale: 0.4, opacity: 0, rotate: open ? -45 : 45 }}
            animate={{ scale: 1, opacity: 1, rotate: 0 }}
            exit={{ scale: 0.4, opacity: 0 }}
            transition={pop}
            className="flex"
          >
            {open ? <XIcon aria-hidden="true" className="size-5" /> : <ChatIcon aria-hidden="true" className="size-5" />}
          </motion.span>
        </AnimatePresence>
      </Button>
      </span>
      <AnimatePresence>
        {unread > 0 && !open ? (
          <motion.span
            key="badge"
            aria-hidden="true"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            exit={{ scale: 0 }}
            transition={pop}
            className="absolute -top-1 -right-1 flex size-5 items-center justify-center rounded-full bg-marketing-orange-surface text-xs font-semibold text-marketing-orange-ink ring-2 ring-card"
          >
            {unread}
          </motion.span>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
